/**
 * jobTierRequest is PUT /api/jobs/{id}/tier's own request body - the same
 * four string values queueTaskDTO.Tier already reports (buildJobsSnapshot's
 * own toDTO), so the frontend can round-trip a row's Tier field straight
 * back as a request without a separate encoding to keep in sync.
 */
export interface JobTierRequest {
  tier: JobTier
}

export interface JobsSnapshot {
  inFlight: QueueTask[]
  /**
   * Queued is the waiting tasks in dispatch order - all of them from GET
   * /api/jobs and the "jobs" topic, only the first jobsQueueLimit from the
   * "jobsQueue" topic. QueuedTotal counts them all either way.
   */
  queued: QueueTask[]
  queuedTotal: number
  /**
   * NarrationLeft sums queueTaskDTO.Chars per book over every in-flight
   * and queued task, listed or not, most left first - the "time left"
   * estimate's input for a client holding a capped Queued.
   */
  narrationLeft?: BookNarration[]
  /**
   * Paused mirrors jobs.Manager.Paused() - see handlePauseJobs/
   * handleResumeJobs, the Jobs dashboard's own pause/resume button.
   */
  paused: boolean
  /**
   * Drained is jobs.Manager.Drained(): paused, everything that was in
   * flight finished and resident models unloaded - from then until
   * resume, only explicit previews run (see POST /api/jobs/pause?drain=1).
   */
  drained: boolean
  /**
   * NarrationCharsPerSecond is jobs.Manager.Throughput: how fast
   * narration has been rendering lately, in characters of paragraph text
   * per second across every generation slot together, rounded to 0.1.
   * Omitted (0) until there's a recent continuous run to measure - no
   * estimate is better than a wild one.
   */
  narrationCharsPerSecond?: number
  /**
   * LastNarrationCharsPerSecond is the same measurement for the most
   * recent run even after it ended (jobs.Manager.LastThroughput) - the
   * library's "time to finish narrating" estimate for books with nothing
   * queued. Omitted (0) until anything has been measured since startup.
   */
  lastNarrationCharsPerSecond?: number
  /**
   * NarrationRealtimeFactor is jobs.Manager.RealtimeFactor: the same run
   * NarrationCharsPerSecond measures, as seconds of audio rendered per
   * wall-clock second (12 = an hour of narration every five minutes),
   * rounded to 0.1. Omitted (0) whenever that is.
   */
  narrationRealtimeFactor?: number
  /**
   * WorkLeft is jobs.Manager.WorkLeft over every in-flight and queued
   * task, listed or not: what is left of each kind of work other than
   * narration, with an estimate of how long it will take, most first.
   */
  workLeft?: KindWork[]
}

/**
 * jobsSummaryDTO is the job queue in a few numbers: what a screen that
 * only wants the narration rate or a queue count reads instead of
 * jobsSnapshotDTO, which lists every task - 29,000 of them (20 MB of JSON)
 * with three books queued for generation, enough to run the Android app
 * out of memory on its library screen.
 */
export interface JobsSummary {
  /**
   * InFlight and Queued count the tasks jobsSnapshotDTO lists.
   */
  inFlight: number
  queued: number
  /**
   * Paused and Drained are jobsSnapshotDTO's.
   */
  paused: boolean
  drained: boolean
  /**
   * The narration rates are jobsSnapshotDTO's, omitted (0) the same way.
   */
  narrationCharsPerSecond?: number
  lastNarrationCharsPerSecond?: number
  narrationRealtimeFactor?: number
}

/**
 * kindWorkDTO is one kind's entry in jobsSnapshotDTO.WorkLeft.
 */
export interface KindWork {
  /**
   * Kind is queueTaskDTO.Kind.
   */
  kind: string
  tasks: number
  /**
   * TypicalSeconds is how long one task of this kind has been taking
   * lately (the mean of its last few runs). Omitted (0) until one has
   * finished since startup.
   */
  typicalSeconds?: number
  /**
   * Seconds estimates the wall-clock time until all of them are done -
   * Tasks x TypicalSeconds over how many run at once. Omitted (0) when
   * TypicalSeconds is.
   */
  seconds?: number
}

export interface LanguagesResponse {
  languages: string[]
}

/**
 * lexiconEntryDTO is one pronunciation rule (store.LexiconEntry) - shared
 * by every book in the book's series (store.SeriesScope), like the
 * character roster.
 */
export interface LexiconEntry {
  id: string
  term: string
  replacement: string
  caseSensitive: boolean
  /**
   * Prefix: the rule also covers words starting with Term (see
   * pronounce.LexiconEntry.Prefix).
   */
  prefix: boolean
  /**
   * Global: the rule applies to every book, not just this series.
   */
  global: boolean
  /**
   * Matches is how many paragraphs in this book the rule applies to.
   */
  matches: number
  /**
   * MatchedWords is the distinct words it respells in this book, as
   * written (whole words for a Prefix rule) - see lexiconMatches.
   */
  matchedWords: string[]
}

/**
 * lexiconMatchesDTO is what a rule matches in one book - the lexicon
 * editor's "what will this respell?" check, before or after saving.
 */
export interface LexiconMatches {
  paragraphs: number
  /**
   * Words is the distinct matched words (case-insensitively), at most
   * maxLexiconMatchedWords, most frequent first.
   */
  words: string[]
  /**
   * MoreWords counts distinct words past Words' cap.
   */
  moreWords?: number
}

/**
 * lexiconSuggestionDTO is a word from the character roster that might want
 * a pronunciation rule.
 */
export interface LexiconSuggestion {
  term: string
  /**
   * Lines is how many dialogue lines in this book the character whose
   * name contains Term speaks - the ranking.
   */
  lines: number
  /**
   * Unusual is a spelling heuristic (see unusualSpelling): letter
   * combinations TTS models tend to guess at. Unusual words sort first.
   */
  unusual: boolean
}

/**
 * Lighting is one music region's room-lighting cue (music_regions.lighting,
 * a native JSON column - NULL until the lighting sub-pass reaches the
 * region). Deliberately device-agnostic: an sRGB color plus a brightness
 * and a named effect, which a client maps onto whatever lights it drives.
 */
export interface Lighting {
  /**
   * Description is the lighting sub-pass's own short description of the
   * light ("dim flickering candlelight in a stone cellar") - display only.
   */
  description?: string
  /**
   * Color is the base color, "#rrggbb".
   */
  color: string
  /**
   * Accent is a second "#rrggbb" color the effect moves toward (a
   * shimmer's other color, a lightning flash's tint, a siren's second
   * color) - "" for none.
   */
  accent?: string
  /**
   * Brightness is 1-100, a fraction of the client's own brightness cap
   * rather than an absolute level.
   */
  brightness: number
  /**
   * Effect is how the light moves over time - see LightEffect.
   */
  effect: LightEffect
}

export interface LlmTestResponse {
  text: string
}

export interface LookaheadRequest {
  chapterIdx: number
  paragraphIdx: number
  /**
   * Optional: how many paragraphs ahead to generate. Omitted/0 means
   * jobs.LookaheadParagraphCount; clamped to jobs.MaxLookaheadParagraphCount.
   */
  paragraphCount?: number
  /**
   * ClientID names this reader: any string the client makes up and keeps
   * (random, per installation). Each reader's window is tracked on its
   * own - when it moves, what only it was waiting for is dropped - so two
   * devices on one book don't cancel each other's. Optional; clients
   * that send none share one.
   */
  clientId?: string
}

export interface MarkReadRequest {
  read: boolean
}

export interface MergeCharacterRequest {
  /**
   * TargetName is who every one of the series' paragraphs currently
   * attributed to this character should be reattributed to instead -
   * "Narrator" (a sentinel, not a real character row) or another
   * character's exact name.
   */
  targetName: string
  /**
   * AsRole makes the target a generic role label (store.Character.
   * IsRole, created as one or turned into one) and skips adding the
   * merged-away name as its alias - for folding a descriptor-named
   * "character" ("the older man") into its kind ("Man"), where the
   * description is no name the target goes by.
   */
  asRole?: boolean
}

export interface MoveChapterRequest {
  /**
   * To is the idx the chapter takes.
   */
  to: number
}

/**
 * musicRegionDTO is one store.MusicRegion, reshaped for the frontend's own
 * background-music playback engine (see store.MusicRegion's own doc
 * comment for the generation pipeline this reflects). AudioURL is only
 * set once Status is AudioReady - the same "no URL until it means
 * something" convention paragraphDTO already uses.
 */
export interface MusicRegion {
  id: string
  startIdx: number
  endIdx: number
  mood: string
  /**
   * Prompt is the actual Stable Audio generation prompt ScoreMusic wrote
   * for this region (store.MusicRegion.Prompt) - Mood is just a short
   * label for compact display (table/badge text); Prompt is the fuller
   * "score" a reader can see without needing to actually hear the
   * result, surfaced by the reader's annotations view as this region's
   * own boundary marker tooltip (see ChapterSection.MusicRegionBoundary).
   */
  prompt: string
  /**
   * Ambience is the region's ambient-soundscape prompt
   * (store.MusicRegion.Ambience), mixed under the music - "" for none.
   */
  ambience?: string
  /**
   * "cut" or "continuation" - see store.MusicTransition
   */
  transition: 'cut' | 'continuation'
  /**
   * Lighting is the region's room-lighting cue from the ambience pass's
   * lighting sub-pass - absent until that sub-pass reaches the region.
   * Clients drive the actual lights (Philips Hue) from it themselves.
   */
  lighting?: Lighting | null
  status: AudioStatus
  error?: string
  durationSeconds: number
  audioUrl?: string
}

export interface Paragraph {
  idx: number
  text: string
  audioStatus: AudioStatus
  audioError?: string
  durationSeconds?: number
  audioUrl?: string
  /**
   * AudioPointerSeconds is set only when this paragraph is a scare-quote
   * merge group pointer (store.AudioState.PointerOffset > 0): the time,
   * in seconds within AudioURL's own shared clip, where this paragraph's
   * own content actually begins - AudioURL itself already resolves to
   * whichever paragraph holds that shared recording (see resolveAudioID).
   * The frontend player uses this to know when playback (which it never
   * seeks or restarts at a merge group's own internal boundaries - see
   * usePlayback.ts) has reached this paragraph's own span, for
   * highlighting/position-reporting purposes only. Omitted (0) for a
   * paragraph with its own real file, which always begins at the very
   * start of AudioURL's clip.
   */
  audioPointerSeconds?: number
  /**
   * Speaker is "" (never attributed) or "Narrator", or a character name -
   * see store.Paragraph.Speaker. Only actually changes this paragraph's
   * narration voice when the book has MultiVoice on (see
   * internal/narration.Resolver) and the named character has a voice
   * assigned - otherwise purely informational.
   */
  speaker?: string
  /**
   * SpeakerIndex tells apart several unnamed people sharing Speaker's
   * role label in one conversation ("Guard 2") - see
   * store.Paragraph.SpeakerIndex. Omitted (0) for a line with no number.
   */
  speakerIndex?: number
  /**
   * Label is text to show before this paragraph that is never spoken: a
   * play's speaker label ("THESEUS.") and any direction on how the line
   * is delivered - see store.Paragraph.Label. Omitted outside a play.
   */
  label?: string
  /**
   * Inline marks this paragraph as a split-out continuation of the
   * previous one, not the start of a new visual paragraph - see
   * store.Paragraph.Inline. The frontend should render consecutive
   * Inline paragraphs (and contentItemDTO's own Inline, below) joined
   * into one paragraph block rather than with a break between them,
   * while still treating each as its own playback/highlight unit.
   */
  inline?: boolean
  /**
   * IsQuote marks this as an actual quoted-dialogue span, as opposed to
   * narration/description - see store.Paragraph.IsQuote. This, not
   * Speaker being non-empty, is what tells the frontend's annotations
   * view a segment is dialogue: an unattributed quote still has
   * Speaker == "" but is dialogue all the same.
   */
  isQuote?: boolean
  /**
   * ScareQuote marks an IsQuote paragraph as NOT actually spoken dialogue
   * despite looking like it structurally - see store.Paragraph.ScareQuote.
   * Always false for a non-IsQuote paragraph.
   */
  scareQuote?: boolean
  /**
   * Emotion is this paragraph's effective delivery emotion (an
   * internal/emotions id - see store.Paragraph.EffectiveEmotion), omitted
   * for neutral. Only ever set on real dialogue.
   */
  emotion?: string
  /**
   * DirectionMarks is every inline delivery tag (today only Higgs's
   * "<|prosody:pause|>") the generation text for this paragraph carries
   * under whichever clone model it's resolved to narrate through, each
   * pinned to where it's inserted in Text (see directionMarkDTO.Offset)
   * so the frontend can render an inline caret there. Empty for the
   * common case.
   */
  directionMarks?: DirectionMark[]
  /**
   * PronunciationMarks is every resolved pronunciation substitution
   * active on this paragraph (e.g. "Dr." -> "Doctor"), each pinned to
   * the word it replaces (see pronunciationMarkDTO.Offset) so the
   * frontend can render a caret directly over it. Unlike DirectionMarks,
   * not clone-model-scoped - see store.Paragraph.Pronunciation's own
   * doc comment. Empty for the common case (no ambiguous abbreviation
   * found in this paragraph).
   */
  pronunciationMarks?: PronunciationMark[]
  /**
   * Table is set for a paragraph read from a table in the source book.
   */
  table?: Table | null
  /**
   * Words is a [{text,start,end}] array from the ttsworker's
   * forced alignment (see ttsworker.Manager.Align), or "[]" before
   * alignment has run - always present (unlike the websocket push's
   * Words, which is omitted for updates that aren't about alignment)
   * since this is a full paragraph snapshot, not a patch.
   */
  words: WordTiming[]
  /**
   * SFX* mirror store.Paragraph's own sound-effect test fields - see
   * its doc comments. SFXAudioURL is set only once SFXStatus ==
   * store.AudioReady, the same "URL only when actually fetchable"
   * convention AudioURL follows.
   */
  sfxPrompt?: string
  sfxStatus?: '' | 'generating' | 'ready' | 'error'
  sfxError?: string
  sfxAudioUrl?: string
  sfxDurationSeconds?: number
  /**
   * SFXTriggerWord mirrors store.Paragraph.SFXTriggerWord - which word
   * (a 0-based index into Words above) playback should start the sound
   * effect at, once ready.
   */
  sfxTriggerWord?: number
  /**
   * ContentHash/AudioHash are this paragraph's leaves in the offline-sync
   * hash tree (see manifest.go): ContentHash covers what an offline copy
   * stores about the paragraph's text and annotations, AudioHash what
   * identifies its audio (resolved voice, status, backing clip, duration,
   * pointer) - so a client can tell "refresh the metadata" apart from
   * "re-download the .wav".
   */
  contentHash: string
  audioHash: string
}

/**
 * paragraphEditDTO is one recorded manual correction (store.ParagraphEdit):
 * the machine's value before the first edit, and the reader's latest.
 * Speakers read "Narrator" where the store holds "".
 */
export interface ParagraphEdit {
  chapterIdx: number
  paragraphIdx: number
  field: ParagraphEditField
  original: string
  value: string
  editedAt: number
  text: string
}

export interface ParagraphEditsResponse {
  edits: ParagraphEdit[]
}

/**
 * Passes is a chapter's own book-preprocess pipeline progress
 * (chapters.passes, stored as a JSON object - the same "flexible,
 * independent facts" shape tts_tags/pronunciation
 * already use their own JSON columns for, rather than one forward-only
 * ChapterState enum this replaced). A struct, not a map, on the Go side so
 * call sites get a typed field (ch.Passes.Direction) instead of a
 * string-keyed lookup a typo could silently miss; the column itself
 * stays a flexible JSON object so a future pass can be added as just
 * another field with no schema change.
 */
export interface Passes {
  /**
   * Attribution is set once speaker attribution
   * (internal/speakerattr.Client.AttributeChapter, via
   * httpapi.attributeChapter) has completed over the whole chapter at
   * least once, in one uninterrupted pass (possibly across several
   * paused/resumed continuations - never set on a pause or a genuine
   * failure partway through, only a full completion).
   */
  attribution: boolean
  /**
   * ScareQuote is set once scare-quote tagging
   * (internal/speakerattr.Client.ScareQuoteChapter, a jobs.KindScareQuote
   * task - see httpapi.scareQuoteChapterForJob) has completed over the
   * whole chapter, persisting Store.SetParagraphScareQuotes. Both
   * attribution waits on this
   * (jobs.Manager.scareQuoteDependency).
   */
  scareQuote: boolean
  /**
   * Direction is set once emotion labeling
   * (internal/speakerattr.Client.EmotionChapter, via
   * httpapi.directChapter - any clone model) has completed over the whole
   * chapter at least once, the same "full pass, not a pause/failure" contract as
   * Attribution. Fully independent of Attribution - a
   * reader can trigger "Tag directions" directly on a chapter that was
   * never attributed via the per-chapter button, bypassing
   * runBookPipeline's own attribute-then-tag ordering entirely, and this
   * struct (unlike the old single ChapterState enum it replaced)
   * represents that combination just fine.
   */
  direction: boolean
  /**
   * Pronunciation is set once pronunciation resolution
   * (internal/speakerattr.Client.ResolvePronunciation, a
   * jobs.KindPronunciation task via httpapi.pronounceChapter) has
   * completed a full pass over the chapter - Direction's own contract,
   * but its own pass.
   */
  pronunciation: boolean
  /**
   * Ambience is set once the ambience pass's music sub-pass
   * (internal/speakerattr.Client.ScoreMusic, via httpapi.ambienceChapter)
   * has completed a full, uninterrupted pass over this chapter (never on
   * a pause or a genuine failure partway through) - Direction's own
   * "full pass, not a pause/failure" contract, and just as independent of
   * Attribution/Direction as Direction itself is: a reader
   * can trigger the ambience pass for a chapter regardless of whether
   * it's ever been attributed/direction-tagged. Triggered by
   * httpapi.handleRunChapterAmbience (the Speakers page's per-chapter
   * button/bulk actions, book preprocessing's own ambience phase, or the
   * reader lazily running whichever chapter it's currently on) -
   * deliberately NOT gated on store.Book.MusicEnabled: that toggle only
   * controls whether a scored region's audio actually gets generated
   * (jobs.Manager.MaybeAdvanceChapterMusic), not whether scoring itself
   * can run (see Book.MusicEnabled's own doc comment). Stored as
   * "music" until the pass was renamed (and backfilled by hand).
   */
  ambience: boolean
  /**
   * Lighting is set once the ambience pass's lighting sub-pass
   * (internal/speakerattr.Client.DescribeLighting, via
   * httpapi.lightChapter) has given every one of the chapter's music
   * regions a MusicRegion.Lighting cue. Runs after the music sub-pass in
   * the same task (it lights the regions scoring produced), but is its
   * own flag so a chapter scored before lighting existed - Ambience set,
   * Lighting not - gets just the lighting sub-pass on its next ambience
   * run, without re-scoring its music.
   */
  lighting: boolean
  /**
   * Summary is set once the summary pass (internal/speakerattr.Client.
   * SummarizeChapter, a jobs.KindSummary task via httpapi.
   * summarizeChapter) has stored the chapter's ChapterNotes. Speaker
   * attribution and the ambience pass wait on it (jobs.Manager.
   * summaryDependency) to read its cast and scenes.
   */
  summary: boolean
}

/**
 * PatchMessage carries the changes since the value the client holds.
 */
export interface PatchMessage {
  type: 'patch'
  id: string
  /**
   * Ops' wire shape comes from Op.MarshalJSON.
   */
  ops: LiveOp[]
}

export interface PatreonSessionRequest {
  /**
   * SessionID is the session_id cookie of a browser signed in to
   * patreon.com; "" signs the library out.
   */
  sessionId: string
}

export interface Position {
  chapterIdx: number
  paragraphIdx: number
  seconds: number
}

export interface PronounsResponse {
  pronouns: string
}

/**
 * pronunciationMarkDTO is one resolved pronunciation substitution pinned
 * to where it applies in p.Text, so the frontend can render a caret
 * directly over the exact word it replaces (see PronunciationCaret in
 * ParagraphText.tsx) - the pronunciation-resolution counterpart of
 * directionMarkDTO, but never clone-model-scoped (see
 * store.Paragraph.Pronunciation's own doc comment).
 */
export interface PronunciationMark {
  /**
   * Offset/Length are rune (Unicode code point) indices/counts into
   * Text, not byte ones - see directionMarkDTO.Offset's own doc comment
   * for why (JS string indexing is UTF-16-code-unit-based). Every
   * abbreviation pronunciationCandidates matches is plain ASCII, so
   * byte and rune counts are identical in practice, but converting
   * properly here costs nothing and keeps this consistent with
   * directionMarkDTO rather than relying on that coincidence.
   */
  offset: number
  length: number
  /**
   * Original is the exact text this mark covers (e.g. "Dr."), sent
   * alongside Replacement so the frontend's hover tooltip can show both
   * without needing to re-derive Original by slicing Text itself.
   */
  original: string
  replacement: string
}

export interface QueueTask {
  /**
   * ID is jobs.QueueTask.ID verbatim - the handle Cancel (DELETE
   * /api/jobs/{id}) takes, and what the frontend keys a dashboard row on.
   */
  id: string
  /**
   * Kind is one of: "voice_clone" | "voice_design" | "voice_design_preview"
   * | "voice_provision" | "speaker_attribution" | "speaker_characterization"
   * | "speech_direction" | "ambience" | "scare_quote_tagging" |
   * "chapter_summary" | "chapter_embedding" | "book_setting" (per-item work, see
   * jobs.Kind) or
   * "pipeline_scare_quote" | "pipeline_attribution" |
   * "pipeline_characterization" |
   * "pipeline_voice_provision" | "pipeline_direction" | "pipeline_ambience"
   * | "pipeline_summary" | "pipeline_embedding"
   * (one of a book's own preprocessing phases - see
   * jobs.EnqueuePipeline/toPipelineQueueTask; deliberately "pipeline_"-
   * prefixed so these can never collide with the per-item kind sharing a
   * phase's own bare name, e.g. "voice_provision").
   */
  kind: string
  /**
   * Label is a human-readable identifier for a kind that isn't chapter/
   * paragraph-scoped - the character's name for "speaker_characterization",
   * or the fixed string "Whole book" for every "pipeline_*" kind (see
   * jobs.toPipelineQueueTask) - "" for every other kind, which already has
   * a chapter/paragraph to show (see jobs.QueueTask.Label).
   */
  label?: string
  bookId: string
  bookTitle: string
  /**
   * ChapterIdx/ChapterTitle are meaningless (0/"") for
   * "speaker_characterization", which is character- rather than
   * chapter-scoped - see Label above.
   */
  chapterIdx: number
  chapterTitle: string
  /**
   * ParagraphIdx is meaningless (0) for the two LLM kinds
   * ("speaker_attribution"/"speaker_characterization"), which aren't
   * paragraph-scoped; for "music_live_generation" it's the first
   * paragraph of the task's one music region - the frontend should key its display on Kind
   * rather than assuming every task has a paragraph.
   */
  paragraphIdx: number
  tier: JobTier
  /**
   * PresetID/Instruct are "" for a "speaker_attribution" task, and for a
   * "voice_design" task PresetID alone is "" (a pure custom instruct with
   * no preset backing it) - the frontend resolves PresetID to a friendly
   * name against the built-in and custom preset lists it already fetches
   * elsewhere, falling back to Instruct when there's no preset to resolve.
   */
  presetId: string
  instruct: string
  /**
   * Attempt is jobs.QueueTask.Attempt verbatim - 0 for a task on its
   * first ever dispatch, only bumped by a genuine failure-retry, never
   * by a cooperative pause (see its own doc comment). The frontend uses
   * this to tell "this is stuck retrying after real failures" apart
   * from "this is just slowly working through a long chapter one batch
   * at a time" - both can look identical (the same row reappearing
   * over and over) without it.
   */
  attempt: number
  /**
   * Emotion is jobs.QueueTask.Emotion verbatim - the emotion variant a
   * clone task's line generates in, "" for neutral.
   */
  emotion?: string
  /**
   * Chars is jobs.QueueTask.Chars verbatim - how much paragraph text a
   * narration task ("voice_clone"/"voice_design") renders, omitted for
   * every other kind. Summed over a book's narration tasks and divided by
   * jobsSnapshotDTO.NarrationCharsPerSecond, it's the Jobs views' "time
   * left" estimate.
   */
  chars?: number
  /**
   * Remaining is jobs.QueueTask.Remaining verbatim - for a running
   * "pipeline_*" row, how many of the tasks it fanned out are still
   * queued or in flight. Omitted for every other row, and for a group
   * that hasn't started.
   */
  remaining?: number
  /**
   * RemainingSeconds estimates how long those Remaining tasks take run
   * on their own, with nothing else in the queue: each kind's count x
   * how long one has been taking lately over how many run at once, and
   * narration at the measured rate. Omitted (0) when nothing about them
   * can be estimated yet. RemainingPartial says some of them couldn't
   * be, so the real figure is higher.
   */
  remainingSeconds?: number
  remainingPartial?: boolean
}

/**
 * queuedResponse is every 202 body: how many background tasks the request
 * enqueued (1 for a single-item enqueue, even if it joined one already
 * queued). A mutation with nothing to report answers 204 instead - see
 * writeNoContent.
 */
export interface QueuedResponse {
  queued: number
}

